// Simple deterministic shard assignment (example)
function gatewayShardForUser(userId, totalShards) {
  // consistent, fast, deterministic mapping
  const hash = Number(BigInt.asUintN(64, BigInt('0x' + require('crypto').createHash('sha1').update(userId).digest('hex').slice(0,16))))
  return hash % totalShards
}

// usage
console.log(gatewayShardForUser('user_1234', 256))
